<div class="row g-4"><div class="col-lg-7"><div class="card shadow-sm"><div class="card-header">Użytkownicy</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>ID</th><th>Nazwa</th><th>E-mail</th><th>Role</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><?= e((string) $user['id']) ?></td><td><?= e($user['name']) ?></td><td><?= e($user['email']) ?></td><td><?= e($user['roles']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div><div class="col-lg-5"><div class="card shadow-sm"><div class="card-body"><h1 class="h5">Dodaj / zaktualizuj użytkownika</h1><form method="post" action="/admin/users"><input type="hidden" name="<?= e($csrfTokenName) ?>" value="<?= e($csrfToken) ?>"><div class="mb-3"><label class="form-label">Nazwa</label><input name="name" class="form-control" required></div><div class="mb-3"><label class="form-label">E-mail</label><input type="email" name="email" class="form-control" required></div><div class="mb-3"><label class="form-label">Hasło</label><input type="password" name="password" class="form-control" required></div><div class="mb-3"><label class="form-label">Rola</label><select name="role" class="form-select"><?php foreach ($roles as $role): ?><option value="<?= e($role['slug']) ?>"><?= e($role['name']) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary">Zapisz</button></form></div></div></div></div>
